package com.learnagent.memory;

import com.fasterxml.jackson.core.type.TypeReference;import com.fasterxml.jackson.databind.ObjectMapper;import com.learnagent.course.CourseService;import com.learnagent.quiz.*;import com.learnagent.rag.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.time.*;import java.util.*;import org.springframework.ai.chat.client.ChatClient;import org.springframework.ai.document.Document;import org.springframework.beans.BeansException;import org.springframework.beans.factory.ObjectProvider;import org.springframework.http.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;
@Service public class FlashcardService{private final FlashcardRepository cards;private final FlashcardReviewStateRepository states;private final QuizRepository quizzes;private final QuestionRepository questions;private final CourseService courses;private final LocalKnowledgeService knowledge;private final ObjectProvider<ChatClient.Builder>chat;private final FsrsSchedulerService fsrs;private final KnowledgeGraphService graph;private final ObjectMapper json;private final Clock clock;public FlashcardService(FlashcardRepository cards,FlashcardReviewStateRepository states,QuizRepository quizzes,QuestionRepository questions,CourseService courses,LocalKnowledgeService knowledge,ObjectProvider<ChatClient.Builder>chat,FsrsSchedulerService fsrs,KnowledgeGraphService graph,ObjectMapper json,Clock clock){this.cards=cards;this.states=states;this.quizzes=quizzes;this.questions=questions;this.courses=courses;this.knowledge=knowledge;this.chat=chat;this.fsrs=fsrs;this.graph=graph;this.json=json;this.clock=clock;}@Transactional public int fromSubmission(UUID quizId,QuizDtos.Submission submission){Quiz quiz=quizzes.findById(quizId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Quiz not found."));Map<UUID,Question>questionMap=new HashMap<>();questions.findByQuizId(quizId).forEach(question->questionMap.put(question.getId(),question));int created=0;for(QuizDtos.Result result:submission.results()){if(result.correct())continue;Question question=questionMap.get(result.questionId());if(question==null)continue;String source=question.getSourceJson();String back="正确答案："+result.correctAnswer()+"\n\n解释："+Optional.ofNullable(result.explanation()).orElse("请结合课程资料复习。")+"\n\n易错原因：本题在测验中回答错误。";if(createCandidate(quiz.getCourseId(),quizId,question.getId(),null,FlashcardType.BASIC,question.getContent(),back,result.knowledgePoint(),source).isPresent())created++;}return created;}@Transactional public List<MemoryDtos.CardView>generate(MemoryDtos.GenerateRequest request){courses.get(request.courseId());int limit=Math.max(1,Math.min(request.limit()==null?10:request.limit(),10));List<Document>excerpts=knowledge.search(request.courseId(),"课程核心概念、定义、规则、易错点与应用");if(excerpts.isEmpty())throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"No READY course material was found.");List<MemoryDtos.SourceRef>sourceRefs=excerpts.stream().map(document->source(document,request.documentId())).distinct().toList();String sourceJson=write(sourceRefs);ChatClient.Builder builder=availableBuilder();if(builder==null)throw new AiFeatureUnavailableException("AI_PROVIDER_NOT_CONFIGURED: flashcard generation requires a chat provider.");String context=excerpts.stream().map(Document::getText).reduce("",(left,right)->left+"\n"+right);MemoryDtos.GeneratedMemorySet generated=builder.build().prompt().system("根据课程资料生成高质量中文记忆卡片与概念关系。卡片正面必须可独立理解，背面简洁准确。仅使用资料内事实。关系只能是 PREREQUISITE、RELATED、PART_OF。返回不超过指定数量的卡片。").user("生成最多 "+limit+" 张候选卡。资料：\n"+context).call().entity(MemoryDtos.GeneratedMemorySet.class);if(generated==null||generated.cards()==null||generated.cards().isEmpty())throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"AI_GENERATION_FAILED: no flashcards generated.");List<MemoryDtos.CardView>created=new ArrayList<>();for(var candidate:generated.cards().stream().limit(limit).toList()){if(candidate.front()==null||candidate.front().isBlank()||candidate.back()==null||candidate.back().isBlank()||candidate.knowledgePoint()==null||candidate.knowledgePoint().isBlank())continue;createCandidate(request.courseId(),null,null,request.documentId(),candidate.cardType()==null?FlashcardType.BASIC:candidate.cardType(),candidate.front(),candidate.back(),candidate.knowledgePoint(),sourceJson).map(this::view).ifPresent(created::add);}if(generated.nodes()!=null)generated.nodes().stream().filter(node->node.name()!=null&&!node.name().isBlank()).forEach(node->graph.ensureNode(request.courseId(),node.name(),sourceJson));if(generated.edges()!=null)generated.edges().forEach(edge->{if(edge.relation()!=null)graph.addEdge(request.courseId(),edge.from(),edge.to(),edge.relation(),sourceJson);});return created;}@Transactional(readOnly=true)public List<MemoryDtos.CardView>list(UUID courseId,FlashcardStatus status){List<Flashcard>values=courseId==null?cards.findByStatusOrderByCreatedAtDesc(status):cards.findByCourseIdAndStatusOrderByCreatedAtDesc(courseId,status);return values.stream().map(this::view).toList();}@Transactional public MemoryDtos.CardView update(UUID id,MemoryDtos.CardUpdate request){Flashcard card=required(id);card.edit(required(request.front()),required(request.back()),required(request.knowledgePoint()),request.cardType()==null?card.getCardType():request.cardType());return view(card);}@Transactional public MemoryDtos.CardView approve(UUID id){Flashcard card=required(id);if(sources(card.getSourceJson()).isEmpty())throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"A traceable source is required before approval.");card.approve();if(states.findById(id).isEmpty()){var initial=fsrs.initialize(id,clock.instant());states.save(new FlashcardReviewState(id,initial.cardJson(),initial.due()));}graph.ensureNode(card.getCourseId(),card.getKnowledgePoint(),card.getSourceJson());graph.refresh(card.getCourseId(),card.getKnowledgePoint());return view(card);}@Transactional public List<MemoryDtos.CardView>approveBatch(List<UUID>ids){if(ids==null)return List.of();return ids.stream().distinct().map(this::approve).toList();}@Transactional public MemoryDtos.CardView suspend(UUID id){Flashcard card=required(id);card.suspend();graph.refresh(card.getCourseId(),card.getKnowledgePoint());return view(card);}@Transactional public MemoryDtos.CardView reject(UUID id){Flashcard card=required(id);card.reject();return view(card);}@Transactional(readOnly=true)public MemoryDtos.CardView get(UUID id){return view(required(id));}private Optional<Flashcard>createCandidate(UUID course,UUID quiz,UUID question,UUID document,FlashcardType type,String front,String back,String point,String sources){String hash=hash(front+"|"+point);if(cards.findByCourseIdAndContentHash(course,hash).isPresent())return Optional.empty();Flashcard card=cards.save(new Flashcard(course,quiz,question,document,type,front.trim(),back.trim(),point.trim(),sources==null?"[]":sources,hash));graph.ensureNode(course,point,sources==null?"[]":sources);return Optional.of(card);}private MemoryDtos.CardView view(Flashcard card){MemoryDtos.ReviewStateView state=states.findById(card.getId()).map(value->{double retrieval=fsrs.retrievability(value.getFsrsCardJson(),clock.instant());return new MemoryDtos.ReviewStateView(value.getDifficulty(),value.getStability(),retrieval,1-retrieval,value.getDueAt(),value.getLastReviewAt(),value.getReviewCount(),value.getLapseCount());}).orElse(null);return new MemoryDtos.CardView(card.getId(),card.getCourseId(),card.getCardType(),card.getFront(),card.getBack(),card.getKnowledgePoint(),card.getStatus(),sources(card.getSourceJson()),card.getCreatedAt(),card.getApprovedAt(),state);}private MemoryDtos.SourceRef source(Document document,UUID requestedDocument){Object page=document.getMetadata().get("pageNumber");String filename=String.valueOf(document.getMetadata().getOrDefault("filename","课程资料"));UUID documentId=null;try{documentId=UUID.fromString(String.valueOf(document.getMetadata().get("documentId")));}catch(Exception ignored){}return new MemoryDtos.SourceRef("LOCAL",filename,null,filename,page instanceof Number number?number.intValue():null,requestedDocument==null?documentId:requestedDocument);}private Flashcard required(UUID id){return cards.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Flashcard not found."));}private String required(String value){if(value==null||value.isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Flashcard text is required.");return value.trim();}private String hash(String value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.trim().toLowerCase(Locale.ROOT).getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}private String write(Object value){try{return json.writeValueAsString(value);}catch(Exception e){throw new IllegalStateException(e);}}private List<MemoryDtos.SourceRef>sources(String value){if(value==null||value.isBlank()||"[]".equals(value))return List.of();try{return json.readValue(value,new TypeReference<>(){});}catch(Exception ignored){return List.of();}}private ChatClient.Builder availableBuilder(){try{return chat.getIfAvailable();}catch(BeansException e){return null;}}}
